<?php
namespace App\Policies;
use App\Models\{Project,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class ProjectPolicy { use HandlesAuthorization, CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_project');} public function view(User $u,Project $r):bool{return $this->canForRecord($u,'view_project',$r);} public function create(User $u):bool{return $u->can('create_project');} public function update(User $u,Project $r):bool{return !in_array($r->status,['closed','cancelled'],true)&&$this->canForRecord($u,'update_project',$r);} public function delete(User $u,Project $r):bool{return $r->status==='planning'&&$this->canForRecord($u,'delete_project',$r);} public function deleteAny(User $u):bool{return false;} public function forceDelete(User $u,Project $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function restore(User $u,Project $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function replicate(User $u,Project $r):bool{return $this->canForRecord($u,'replicate_project',$r);} public function reorder(User $u):bool{return $u->can('reorder_project');} public function approve(User $u,Project $r):bool{return $this->canForRecord($u,'approve_project',$r);} public function cancel(User $u,Project $r):bool{return $this->canForRecord($u,'cancel_project',$r);} public function close(User $u,Project $r):bool{return $this->canForRecord($u,'close_project',$r);} public function attachProperty(User $u,Project $r):bool{return $this->canForRecord($u,'attach_project_property',$r);} public function detachProperty(User $u,Project $r):bool{return $this->canForRecord($u,'detach_project_property',$r);} public function manageMembers(User $u,Project $r):bool{return $this->canForRecord($u,'manage_project_members',$r);} }
